<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
import { RouterLink, useRoute } from 'vue-router';
import { Box, FullScreen, Aim, RefreshRight, Search, Setting, Upload } from '@element-plus/icons-vue';
import { formatBytes, gaussianUrl, listGaussians } from '@/api/gaussians.js';

const route = useRoute();
const scenes = ref([]), active = ref(null), search = ref(''), loading = ref(false);
const frame = ref(), viewport = ref(), generation = ref(0), status = ref('empty'), error = ref(''), libraryError = ref('');
const sky = ref(true), skyStatus = ref('off'), skyError = ref(''), settings = ref(false), quality = ref('standard');
const background = ref('#07131f'), speed = ref(1), fullscreen = ref(false), stats = ref({ fps: 0, splats: 0, pages: 0 });
const filtered = computed(() => scenes.value.filter(scene => scene.name.toLowerCase().includes(search.value.trim().toLowerCase())));
const iframeUrl = `${import.meta.env.BASE_URL}gaussian-viewer/index.html`;
const statusText = computed(() => ({ empty: '等待选择场景', booting: '正在准备渲染窗口', loading: '正在读取场景', indexed: '正在加载首屏细节', ready: '实时渲染', error: '场景加载失败' })[status.value]);
let controller, timeout, disposed = false;
function send(type, payload = {}) {
  // Vue's nested reactive proxies cannot be passed to another window.
  const message = JSON.parse(JSON.stringify({ channel: 'tiantan-gaussian', type, ...payload }));
  frame.value?.contentWindow?.postMessage(message, window.location.origin);
}
function unload() {
  generation.value++; clearTimeout(timeout); send('dispose'); active.value = null; error.value = ''; skyError.value = '';
  status.value = 'empty'; stats.value = { fps: 0, splats: 0, pages: 0 };
}
async function load(scene) {
  unload(); const current = generation.value; await nextTick();
  if (disposed || current !== generation.value) return;
  active.value = scene; sky.value = scene.skyDefaultEnabled; skyStatus.value = scene.hasSky ? 'loading' : 'off';
  status.value = 'booting';
  timeout = setTimeout(() => { if (status.value === 'booting') { status.value = 'error'; error.value = '渲染窗口未能启动，请刷新后重试。'; } }, 30000);
}
function receive(event) {
  if (event.origin !== window.location.origin || event.source !== frame.value?.contentWindow || event.data?.channel !== 'tiantan-gaussian' || !active.value) return;
  const data = event.data;
  if (data.type === 'ready') {
    clearTimeout(timeout); status.value = 'loading';
    send('load', { model: { ...active.value, mainUrl: gaussianUrl(active.value.mainUrl), skyUrl: active.value.skyUrl ? gaussianUrl(active.value.skyUrl) : null }, sky: sky.value, quality: quality.value });
  }
  if (data.type === 'indexed') { status.value = 'indexed'; send('background', { color: background.value }); send('speed', { value: speed.value }); }
  if (data.type === 'loaded') status.value = 'ready';
  if (data.type === 'error') { error.value = data.message; status.value = 'error'; }
  if (data.type === 'sky') { skyStatus.value = data.status; skyError.value = data.status === 'error' ? data.message : ''; }
  if (data.type === 'stats') stats.value = { fps: data.fps, splats: data.splats, pages: data.pages };
}
async function refresh(first = false) {
  controller?.abort(); const request = new AbortController(); controller = request; loading.value = true; libraryError.value = '';
  try {
    const values = await listGaussians(request.signal); if (disposed) return; scenes.value = values;
    if (active.value && !values.some(scene => scene.id === active.value.id)) unload();
    if (first && route.query.scene) { const target = values.find(scene => String(scene.id) === String(route.query.scene)); if (target) load(target); }
  } catch (failure) { if (failure.name !== 'AbortError') libraryError.value = failure.message; }
  finally { if (controller === request) loading.value = false; }
}
async function toggleFullscreen() {
  try { if (document.fullscreenElement) await document.exitFullscreen(); else await viewport.value.requestFullscreen(); }
  catch { error.value = '浏览器未允许全屏，请检查页面权限。'; }
}
function fullscreenChanged() { fullscreen.value = document.fullscreenElement === viewport.value; }
function changeQuality() { if (active.value) load(active.value); }
onMounted(() => { window.addEventListener('message', receive); document.addEventListener('fullscreenchange', fullscreenChanged); refresh(true); });
onBeforeUnmount(() => { disposed = true; unload(); controller?.abort(); window.removeEventListener('message', receive); document.removeEventListener('fullscreenchange', fullscreenChanged); });
</script>

<template>
  <main class="gaussian-page">
    <header class="page-heading"><div><p>GAUSSIAN SCENES / REALTIME EXPLORATION</p><h1>高斯渲染 <span>实景空间</span></h1><small>在光影与细节之间，探索建筑的真实面貌。</small></div><RouterLink :to="{ path: '/data-import', query: { category: 'GAUSSIAN' } }"><Upload />管理高斯数据 ↗</RouterLink></header>
    <div class="gaussian-workspace">
      <aside class="catalog">
        <header><div><Box /><strong>场景目录</strong><span>{{ scenes.length.toString().padStart(2, '0') }}</span></div><button :disabled="loading" title="刷新场景目录" aria-label="刷新场景目录" @click="refresh(false)"><RefreshRight /></button></header>
        <label class="search"><Search /><input v-model="search" placeholder="搜索场景" aria-label="搜索高斯场景"></label>
        <div v-if="libraryError" class="catalog-empty" role="alert"><strong>暂时无法读取场景库</strong><span>{{ libraryError }}</span><button @click="refresh(false)">重新连接</button></div>
        <div v-else-if="loading && !scenes.length" class="catalog-empty">正在读取场景库…</div>
        <div v-else-if="!filtered.length" class="catalog-empty"><Box /><strong>{{ search ? '没有匹配的场景' : '暂无高斯场景' }}</strong><span>{{ search ? '试试其他名称。' : '导入 RAD 成果后，即可在这里浏览。' }}</span></div>
        <div v-else class="scene-list"><article v-for="(scene, index) in filtered" :key="scene.id" class="scene-card" :class="{ active: active?.id === scene.id }"><div class="scene-symbol"><Box /><span>{{ String(index + 1).padStart(2, '0') }}</span><small>{{ scene.hasSky ? '含天空' : '主体场景' }}</small></div><strong>{{ scene.name }}</strong><div class="scene-meta"><span>{{ formatBytes(scene.totalSize) }}</span><span>{{ scene.chunkCount }} 块</span></div><button class="load-button" @click="active?.id === scene.id ? unload() : load(scene)">{{ active?.id === scene.id ? '卸载场景' : '加载场景' }}<span>{{ active?.id === scene.id ? '×' : '↗' }}</span></button></article></div>
        <footer><i></i><span>按需加载 · 分层细节</span></footer>
      </aside>
      <section ref="viewport" class="viewport">
        <iframe v-if="active" :key="generation" ref="frame" :src="iframeUrl" title="高斯场景渲染窗口" allow="fullscreen" />
        <div v-else class="empty-stage"><div class="scene-emblem"><Box /></div><p>SCENE EXPLORER</p><h2>从一个场景开始</h2><span>选择左侧场景，进入可自由漫游的实景空间。</span><RouterLink v-if="!scenes.length" :to="{ path: '/data-import', query: { category: 'GAUSSIAN' } }">导入高斯成果 ↗</RouterLink><div class="empty-tags"><span>层级细节</span><span>天空效果</span><span>自由漫游</span></div></div>
        <div v-if="active" class="scene-title"><i :class="{ ready: status === 'ready' }"></i><div><strong>{{ active.name }}</strong><span>{{ Number(active.sourceSplatCount).toLocaleString('zh-CN') }} 个原始高斯</span></div></div>
        <div class="toolbar"><div class="sky-control" :class="{ disabled: !active?.hasSky }"><span>天空</span><el-switch v-model="sky" size="small" :disabled="!active?.hasSky" aria-label="天空开关" @change="send('sky', { enabled: sky })" /></div><button :class="{ selected: settings }" title="显示设置" aria-label="显示设置" @click="settings = !settings"><Setting /></button><button :disabled="!active" title="视角复位" aria-label="视角复位" @click="send('reset')"><Aim /></button><button :title="fullscreen ? '退出全屏' : '全屏'" :aria-label="fullscreen ? '退出全屏' : '全屏'" @click="toggleFullscreen"><FullScreen /></button></div>
        <div v-if="settings" class="settings-panel"><h3>显示设置</h3><label>渲染质量<select v-model="quality" @change="changeQuality"><option value="standard">标准 · 100 万点</option><option value="low">流畅 · 50 万点</option></select></label><label>漫游速度 <span>{{ speed }}×</span><input v-model.number="speed" type="range" min="0.2" max="3" step="0.2" @input="send('speed', { value: speed })"></label><label class="color-label">背景颜色<input v-model="background" type="color" @input="send('background', { color: background })"></label><p>点击画面后使用 WASDQE，沿相机方向漫游。</p></div>
        <div v-if="active && ['booting', 'loading', 'indexed'].includes(status)" class="loading-overlay"><i></i><span>{{ statusText }}</span></div>
        <div v-if="error" class="viewer-error" role="alert"><strong>{{ error }}</strong><button v-if="active" @click="load(active)">重新加载</button></div>
        <div v-if="skyError" class="sky-error" role="alert">天空暂不可用：{{ skyError }}<button @click="send('sky', { enabled: true })">重试</button></div>
        <div class="status-bar"><span class="state"><i :class="{ ready: status === 'ready' }"></i>{{ statusText }}</span><span v-if="active">{{ stats.fps || '—' }} FPS</span><span v-if="active">{{ stats.splats.toLocaleString('zh-CN') }} 点</span><span v-if="active">{{ stats.pages }} 页</span><small>拖动旋转 · 右键平移 · 滚轮缩放</small></div>
      </section>
    </div>
  </main>
</template>

